#!/usr/bin/env python3
"""Add a 'Profit Margin %' column to sales_data.xlsx using Excel formulas."""
import sys
import openpyxl

PATH = 'sales_data.xlsx'
wb = openpyxl.load_workbook(PATH)
ws = wb.active

def find_header_row():
    for r in range(1, min(ws.max_row, 6) + 1):
        vals = [ws.cell(row=r, column=c).value for c in range(1, min(ws.max_column, 15) + 1)]
        txt = ' '.join(str(v).lower() for v in vals if v is not None)
        if 'revenue' in txt or 'profit' in txt or 'sales' in txt:
            return r
    return 1

header_row = find_header_row()
headers = {}
for cell in ws[header_row]:
    if cell.value is not None:
        headers[cell.column] = str(cell.value).strip()
print('Sheet:', ws.title, '| Header row:', header_row)
print('Headers:', headers)

def find_col(*keys):
    for col, name in headers.items():
        low = name.lower()
        for key in keys:
            if key in low:
                return col
    return None

rev = find_col('revenue', 'total sales', 'sales amount', 'sales', 'amount')
prof = find_col('profit', 'income', 'earnings')
if not rev or not prof:
    print('ERROR: could not locate revenue/profit columns', file=sys.stderr)
    sys.exit(2)

new_col = None
for col, name in headers.items():
    if 'profit margin' in name.lower():
        new_col = col
        break
if new_col is None:
    new_col = ws.max_column + 1

hdr_cell = ws.cell(row=header_row, column=new_col)
hdr_cell.value = 'Profit Margin %'
hdr_cell.font = openpyxl.styles.Font(bold=True)

for r in range(header_row + 1, ws.max_row + 1):
    if ws.cell(row=r, column=rev).value is None and ws.cell(row=r, column=prof).value is None:
        continue
    cell = ws.cell(row=r, column=new_col)
    cell.value = f'=IFERROR({ws.cell(row=r, column=prof).coordinate}/{ws.cell(row=r, column=rev).coordinate},"")'
    cell.number_format = '0.0%'

wb.save(PATH)
print(f'Added profit margin column at column {new_col} (rows {header_row + 1}-{ws.max_row})')

#!/usr/bin/env python3
"""Verify the Profit Margin % column in sales_data.xlsx."""
import openpyxl

PATH = 'sales_data.xlsx'

wb = openpyxl.load_workbook(PATH)
ws = wb.active
print('=== Formulas (as stored) ===')
errors = []
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    for c in row:
        if isinstance(c.value, str) and c.value.startswith('='):
            if any(e in c.value for e in ('#REF!', '#DIV/0!', '#VALUE!', '#NAME?', '#N/A')):
                errors.append(c.coordinate)
    print([c.value for c in row])

print('\n=== Formatting check (col H) ===')
for r in range(1, ws.max_row + 1):
    c = ws.cell(row=r, column=8)
    print(c.coordinate, '| value:', repr(c.value), '| fmt:', c.number_format)

print('\nFormula error cells:', errors if errors else 'NONE')
